inline void Prepare(PreparedLaunch& prepared, TensorView arg_split_state, TensorView arg_map_state_bf16, TensorView arg_carry, int64_t arg_num_heads, int64_t arg_num_parts, int64_t grid_x, int64_t grid_y, int64_t grid_z, cudaStream_t stream) {
  CheckCudaTensor(arg_split_state, "split_state");
  CheckDtype(arg_split_state, "split_state", 2, 32, 1);
  CheckContiguous(arg_split_state, "split_state");
  CheckCudaTensor(arg_map_state_bf16, "map_state_bf16");
  CheckDtype(arg_map_state_bf16, "map_state_bf16", 4, 16, 1);
  CheckContiguous(arg_map_state_bf16, "map_state_bf16");
  CheckCudaTensor(arg_carry, "carry");
  CheckDtype(arg_carry, "carry", 2, 32, 1);
  CheckContiguous(arg_carry, "carry");
  TVM_FFI_CHECK(arg_num_heads >= -2147483648LL && arg_num_heads <= 2147483647LL, ValueError)
      << "scalar 'num_heads' value " << arg_num_heads
      << " is outside i32 range [-2147483648, 2147483647]";
  TVM_FFI_CHECK(arg_num_parts >= -2147483648LL && arg_num_parts <= 2147483647LL, ValueError)
      << "scalar 'num_parts' value " << arg_num_parts
      << " is outside i32 range [-2147483648, 2147483647]";
  CheckSameCudaDevice(arg_map_state_bf16, arg_split_state, "map_state_bf16", "split_state");
  CheckSameCudaDevice(arg_carry, arg_split_state, "carry", "split_state");
  CheckCurrentCudaDevice(arg_split_state, "split_state");
  TVM_FFI_CHECK(grid_x > 0 && grid_y > 0 && grid_z > 0, ValueError)
      << "launch grid dimensions must be positive, got (" << grid_x << ", " << grid_y
      << ", " << grid_z << ")";

  prepared.retained.clear();
  prepared.retained.reserve(3);
  prepared.retained.push_back(arg_split_state);
  prepared.retained.push_back(arg_map_state_bf16);
  prepared.retained.push_back(arg_carry);

  DLDevice dev = arg_split_state.device();
  static std::mutex smem_mu;
  static auto* smem_status_by_device =
      new std::unordered_map<int, cudaError_t>();
  cudaError_t smem_status = cudaSuccess;
  {
    std::lock_guard<std::mutex> lock(smem_mu);
    auto it = smem_status_by_device->find(dev.device_id);
    if (it == smem_status_by_device->end()) {
      int current_device = -1;
      smem_status = cudaGetDevice(&current_device);
      if (smem_status == cudaSuccess && current_device != dev.device_id) {
        smem_status = cudaErrorInvalidDevice;
      }
      if (smem_status == cudaSuccess) {
        smem_status = cudaFuncSetAttribute(
            reinterpret_cast<const void*>(kernel_cake_kda_affine_unbounded_softplus_scan),
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            66560);
      }
      smem_status_by_device->emplace(dev.device_id, smem_status);
    } else {
      smem_status = it->second;
    }
  }
  TVM_FFI_CHECK(smem_status == cudaSuccess, RuntimeError)
      << "cudaFuncSetAttribute for kernel_cake_kda_affine_unbounded_softplus_scan failed: "
      << cudaGetErrorString(smem_status);
  prepared.p_split_state = arg_split_state.data_ptr();
  prepared.p_map_state_bf16 = arg_map_state_bf16.data_ptr();
  prepared.p_carry = arg_carry.data_ptr();
  prepared.v_num_heads = (int32_t)arg_num_heads;
  prepared.v_num_parts = (int32_t)arg_num_parts;
  prepared.grid = dim3((uint32_t)grid_x, (uint32_t)grid_y, (uint32_t)grid_z);
  prepared.block = dim3(128u, 1u, 1u);
  prepared.kargs[0] = &prepared.p_split_state;
  prepared.kargs[1] = &prepared.p_map_state_bf16;
  prepared.kargs[2] = &prepared.p_carry;
  prepared.kargs[3] = &prepared.v_num_heads;
  prepared.kargs[4] = &prepared.v_num_parts;
}

